SELECT shipment_id, tenant_id, order_id, carrier_id, tracking_no, destination_country, status, created_at, updated_at
FROM tms_shipment
WHERE tenant_id = #{tenantId}
  AND tracking_no = #{trackingNo}

SELECT tenant_id, event_id, shipment_id, status, location, description, occurred_at
FROM tms_tracking_event
WHERE shipment_id = #{shipmentId}
  AND tenant_id = #{tenantId}
ORDER BY occurred_at ASC

