INSERT INTO tms_shipping_cost (
    cost_id, tenant_id, shipment_id, carrier_id, freight_cost, fuel_surcharge, other_fees, total_cost, currency, created_at
)
VALUES (
    #{costId}, #{tenantId}, #{shipmentId}, #{carrierId}, #{freightCost}, #{fuelSurcharge}, #{otherFees}, #{totalCost}, #{currency}, #{createdAt}
)

mapper.select:
SELECT cost_id, tenant_id, shipment_id, carrier_id, freight_cost, fuel_surcharge, other_fees, total_cost, currency, created_at
FROM tms_shipping_cost
WHERE tenant_id = #{tenantId}
  AND carrier_id = #{carrierId}
ORDER BY created_at DESC

SELECT method_id, tenant_id, carrier_id, name, type, rate_type, enabled, created_at, updated_at
FROM tms_shipping_method WHERE tenant_id = #{tenantId}
ORDER BY name ASC

SELECT method_id, tenant_id, carrier_id, name, type, rate_type, enabled, created_at, updated_at
FROM tms_shipping_method WHERE tenant_id = #{tenantId} AND carrier_id = #{carrierId}
ORDER BY name ASC

mapper.update:
UPDATE tms_shipping_rate SET origin = #{origin}, destination = #{destination}, weight_min = #{weightMin},
       weight_max = #{weightMax}, rate = #{rate}, currency = #{currency}, updated_at = #{updatedAt}
WHERE rate_id = #{rateId} AND tenant_id = #{tenantId}

mapper.select:
SELECT rate_id, tenant_id, method_id, origin, destination, weight_min, weight_max, rate, currency, created_at, updated_at
FROM tms_shipping_rate WHERE tenant_id = #{tenantId} AND method_id = #{methodId}
ORDER BY weight_min ASC

SELECT batch_id, tenant_id, carrier_id, shipment_ids, status, created_at, updated_at
FROM tms_shipping_batch WHERE tenant_id = #{tenantId}
ORDER BY created_at DESC
